<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'||gethostname()!=='nextcloud-staging')exit(1);
chdir('/var/www/html');$_SERVER['SCRIPT_FILENAME']='/var/www/html/occ';define('OC_CONSOLE',true);require '/var/www/html/lib/base.php';
\OCP\Server::get(\OCP\App\IAppManager::class)->loadApp('libresign');
$source=$argv[1]??__DIR__.'/../../lib/Service/SigningFieldService.php';
require_once $source;
if(realpath((new ReflectionClass(\OCA\Libresign\Service\SigningFieldService::class))->getFileName())!==realpath($source))throw new RuntimeException('Wrong policy loaded');
use OCA\Libresign\Service\SigningFieldService as Policy;
use OCA\Libresign\Db\FileElement;
$checks=0;$check=static function(bool $ok,string $message)use(&$checks):void{if(!$ok)throw new RuntimeException($message);$checks++;echo 'PASS: '.$message.PHP_EOL;};
$reject=static function(callable $fn,string $message)use($check):void{try{$fn();}catch(\OCA\Libresign\Exception\LibresignException){$check(true,$message);return;}$check(false,$message);};
$field=new FileElement();$field->setId(77);$field->setType('date');$field->setMetadata(['label'=>'Signed on','required'=>true,'useSigningDate'=>true]);
$check(Policy::definition([])===['label'=>'','required'=>true],'legacy definitions keep manual-date behaviour');
$check(Policy::submittedValue($field,[])==='','required automatic date does not require client input');
$first=new DateTimeImmutable('2026-10-26T23:30:00Z');$second=new DateTimeImmutable('2026-10-28T02:00:00Z');
$check(Policy::submittedValue($field,[],$first)==='2026-10-27','server instant converted to stored Africa/Lagos timezone');
$check(Policy::submittedValue($field,[['documentElementId'=>77,'value'=>'1999-12-31']],$first)==='2026-10-27','forged client date cannot override server date');
$check(Policy::submittedValue($field,[['documentElementId'=>77,'value'=>['bad']]],$first)==='2026-10-27','malformed client date is ignored for automatic fields');
$check(Policy::submittedValue($field,[],$second)==='2026-10-28','each sequential signer uses their own signing instant');
$check($first->format(DATE_ATOM)==='2026-10-26T23:30:00+00:00','timezone conversion never mutates the signature timestamp');
$field->setMetadata(['required'=>false,'useSigningDate'=>true,'signingDateTimezone'=>'UTC']);
$check(Policy::submittedValue($field,[],$first)==='2026-10-26','optional automatic field is still filled and respects UTC');
$reject(fn()=>Policy::submittedValue($field,[['documentElementId'=>77],['documentElementId'=>77]],$first),'duplicate automatic field submissions rejected');
$reject(fn()=>Policy::definition(['useSigningDate'=>'true'],'date'),'non-boolean automatic setting rejected');
$reject(fn()=>Policy::definition(['useSigningDate'=>true],'text'),'automatic setting cannot be applied to text');
$reject(fn()=>Policy::definition(['useSigningDate'=>true,'signingDateTimezone'=>'Invalid/Zone'],'date'),'invalid timezone rejected');
$field->setMetadata(['required'=>true,'useSigningDate'=>false]);
$check(Policy::submittedValue($field,[['documentElementId'=>77,'value'=>'2000-02-29']],$first)==='2000-02-29','manual date remains signer chosen');
$reject(fn()=>Policy::submittedValue($field,[],$first),'required manual date cannot be skipped');
$reject(fn()=>Policy::submittedValue($field,[['documentElementId'=>77,'value'=>'2026-02-29']],$first),'manual dates still reject invalid calendar dates');
echo json_encode(['checksPassed'=>$checks,'documentChanges'=>0,'emailsSent'=>0]).PHP_EOL;
